// cmtz-core: reusable Cook-Mertz processor, F_17 (q = 19).
// Generated by cmtz/backends/isa_core.py from cmtz/isa/encoding.py
// (ISA version 1). Do not edit by hand.
//
// program memory 512 x 32, data memory 1024 x 5,
// R0..R31 x 5 bits, X0..X15 x 16 bits, return stack 8.
// status: 0 idle, 1 running, 2 halted, 3 error.
// error:  1 opcode, 2 pc, 3 stack overflow, 4 underflow, 5 RETI, 6 address,
//         7 aborted.
// Step build: pause_req, step_req, resume_req, paused (see emit_core).
// Paused is state S_PAUSE; the host may read memory and registers then.

module cmtz_core (
    input  wire            clk,
    input  wire            start,
    input  wire            abort,
    input  wire            irq,
    input  wire            pause_req,
    input  wire            step_req,
    input  wire            resume_req,
    output wire            paused,
    input  wire [9:0]     cfg_len,
    input  wire [9:0]     cfg_entry,
    input  wire [9:0]     cfg_handler,
    input  wire            cfg_has_handler,
    input  wire            pm_we,
    input  wire [8:0]     pm_addr,
    input  wire [31:0]     pm_wdata,
    input  wire            dm_we,
    input  wire [9:0]     dm_addr,
    input  wire [4:0]      dm_wdata,
    output wire [4:0]      dm_rdata,
    input  wire            r_we,
    input  wire [4:0]      r_addr,
    input  wire [4:0]      r_wdata,
    output wire [4:0]      r_rdata,
    input  wire [3:0]      x_addr,
    output wire [15:0]     x_rdata,
    output wire [1:0]      status,
    output wire [2:0]      error,
    output reg  [31:0]     retired,
    output reg  [31:0]     disp_retired,
    output reg  [9:0]     disp_pc,
    output reg  [15:0]     disp_count,
    output wire            boundary,
    output wire [9:0]     pc_out
);

localparam OP_NOP = 6'd0;
localparam OP_HALT = 6'd1;
localparam OP_ADD = 6'd2;
localparam OP_SUB = 6'd3;
localparam OP_MUL = 6'd4;
localparam OP_MAC = 6'd5;
localparam OP_MULI = 6'd6;
localparam OP_MOV = 6'd7;
localparam OP_LDI = 6'd8;
localparam OP_HORNER = 6'd9;
localparam OP_REDP = 6'd10;
localparam OP_LIX = 6'd11;
localparam OP_ADDIX = 6'd12;
localparam OP_ADDX = 6'd13;
localparam OP_MULX = 6'd14;
localparam OP_FTOX = 6'd15;
localparam OP_LD = 6'd16;
localparam OP_ST = 6'd17;
localparam OP_JMP = 6'd18;
localparam OP_BEQX = 6'd19;
localparam OP_BNEX = 6'd20;
localparam OP_BLTX = 6'd21;
localparam OP_BZ = 6'd22;
localparam OP_BNZ = 6'd23;
localparam OP_CALL = 6'd24;
localparam OP_RET = 6'd25;
localparam OP_RETI = 6'd26;
localparam OP_WAITI = 6'd27;

localparam S_IDLE = 3'd0, S_FETCH = 3'd1, S_EXEC = 3'd2, S_MEM = 3'd3, S_PAUSE = 3'd4;
localparam ST_IDLE = 2'd0, ST_RUN = 2'd1, ST_HALT = 2'd2, ST_ERR = 2'd3;

function [4:0] red_add;
    input [5:0] x;
    reg [5:0] t;
    begin
        t = x;
        if (t >= 6'd34) t = t - 6'd34;
        if (t >= 6'd17) t = t - 6'd17;
        red_add = t[4:0];
    end
endfunction

function [4:0] red_mul;
    input [10:0] x;
    reg [10:0] t;
    begin
        t = x;
        if (t >= 11'd1088) t = t - 11'd1088;
        if (t >= 11'd544) t = t - 11'd544;
        if (t >= 11'd272) t = t - 11'd272;
        if (t >= 11'd136) t = t - 11'd136;
        if (t >= 11'd68) t = t - 11'd68;
        if (t >= 11'd34) t = t - 11'd34;
        if (t >= 11'd17) t = t - 11'd17;
        red_mul = t[4:0];
    end
endfunction

function [4:0] red_hq;
    input [10:0] x;
    reg [10:0] t;
    begin
        t = x;
        if (t >= 11'd1216) t = t - 11'd1216;
        if (t >= 11'd608) t = t - 11'd608;
        if (t >= 11'd304) t = t - 11'd304;
        if (t >= 11'd152) t = t - 11'd152;
        if (t >= 11'd76) t = t - 11'd76;
        if (t >= 11'd38) t = t - 11'd38;
        if (t >= 11'd19) t = t - 11'd19;
        red_hq = t[4:0];
    end
endfunction

function [4:0] red_redp;
    input [4:0] x;
    reg [4:0] t;
    begin
        t = x;
        if (t >= 5'd17) t = t - 5'd17;
        red_redp = t[4:0];
    end
endfunction

reg [2:0]  state = S_IDLE;
reg        pause_pend = 1'b0, stepping = 1'b0, step_done = 1'b0;
reg [1:0]  st = ST_IDLE;
reg [2:0]  err = 3'd0;
reg [9:0] pc = 10'd0;
reg [9:0] saved_pc = 10'd0;
reg        pending = 1'b0, in_h = 1'b0, handled = 1'b0;
reg [3:0] sp = 4'd0;
reg [9:0] stack [0:7];

reg [4:0] R [0:31];
reg [15:0] X [0:15];
reg [31:0] pm [0:511];
reg [4:0] dm [0:1023];
reg [31:0] ir = 32'd0;
reg [4:0] dm_q = 5'd0;

integer i;
initial begin
    for (i = 0; i < 32; i = i + 1) R[i] = 5'd0;
    for (i = 0; i < 16; i = i + 1) X[i] = 16'd0;
    for (i = 0; i < 8; i = i + 1) stack[i] = 10'd0;
    retired = 32'd0; disp_retired = 32'd0; disp_pc = 10'd0;
    disp_count = 16'd0;
end

assign status = st;
assign error = err;
assign boundary = (state == S_FETCH);
assign pc_out = pc;
assign r_rdata = R[r_addr];
assign paused = (state == S_PAUSE);
assign x_rdata = X[x_addr];
assign dm_rdata = dm_q;

// ── decode ──────────────────────────────────────────────────────────
wire [5:0]  op  = ir[31:26];
wire [4:0]  fa  = ir[25:21];
wire [4:0]  fb  = ir[20:16];
wire [4:0]  fc  = ir[15:11];
wire [10:0] imm = ir[10:0];
wire [4:0] ra = R[fa];
wire [4:0] rb = R[fb];
wire [4:0] rc = R[fc];
wire [4:0] irw = imm[4:0];
wire [15:0] xa = X[fa[3:0]];
wire [15:0] xb = X[fb[3:0]];
wire [15:0] xc = X[fc[3:0]];
wire [15:0] simm = {{5{imm[10]}}, imm};
wire [15:0] maddr = xb + {5'd0, imm};
wire        addr_ok = (maddr < 16'd1024);
wire [9:0] target = imm[9:0];
wire [9:0] pc1 = pc + 10'd1;

// ── field ALU ───────────────────────────────────────────────────────
wire [5:0]   add_s  = {1'b0, rb} + {1'b0, rc};
wire [4:0] add_r  = red_add(add_s);
wire [5:0]   sub_s  = (rb >= rc) ? ({1'b0, rb} - {1'b0, rc})
                                 : ({1'b0, rb} + 6'd17 - {1'b0, rc});
wire [4:0] sub_r  = red_add(sub_s);
wire [10:0] mul_x  = rb * rc;
wire [4:0] mul_r  = red_mul(mul_x);
wire [10:0] mac_x  = ra + rb * rc;
wire [4:0] mac_r  = red_mul(mac_x);
wire [10:0] muli_x = rb * irw;
wire [4:0] muli_r = red_mul(muli_x);
wire [10:0] hq_x   = ra * rb + irw;
wire [4:0] hq_r   = red_hq(hq_x);
wire [4:0] redp_r = red_redp(rb);

// ── data memory: host port while idle, core port while running ─────
wire running = (state != S_IDLE);
wire dmcore = running && (state != S_PAUSE);
wire [9:0] dm_a = dmcore ? maddr[9:0] : dm_addr;
wire dm_w = dmcore ? (state == S_EXEC && op == OP_ST && addr_ok) : (dm_we && !running);
wire [4:0] dm_d = dmcore ? ra : dm_wdata;
always @(posedge clk) begin
    if (dm_w) dm[dm_a] <= dm_d;
    dm_q <= dm[dm_a];
end

// ── program memory: host writes while idle; the core reads at pc ────
always @(posedge clk) begin
    if (pm_we && !running) pm[pm_addr] <= pm_wdata;
    ir <= pm[pc[8:0]];
end

// ── control ─────────────────────────────────────────────────────────
task fail(input [2:0] code);
    begin
        st <= ST_ERR; err <= code; state <= S_IDLE;
    end
endtask

task wr(input [4:0] v);
    begin
        if (fa != 5'd0) R[fa] <= v;
    end
endtask

task wx(input [15:0] v);
    begin
        if (fa[3:0] != 4'd0) X[fa[3:0]] <= v;
    end
endtask

task advance;
    begin
        pc <= pc1; retired <= retired + 32'd1; state <= S_FETCH; step_done <= 1'b1;
    end
endtask

task jump(input [9:0] to);
    begin
        pc <= to; retired <= retired + 32'd1; state <= S_FETCH; step_done <= 1'b1;
    end
endtask

always @(posedge clk) begin
    if (irq) pending <= 1'b1;
    if (!running && r_we && r_addr != 5'd0) R[r_addr] <= r_wdata;
    if (pause_req && state != S_IDLE && state != S_PAUSE) pause_pend <= 1'b1;
    if (running && abort) begin
        fail(3'd7);
    end else case (state)
    S_IDLE: if (start || pause_req) begin
        pc <= cfg_entry; sp <= 4'd0; pending <= 1'b0; in_h <= 1'b0;
        handled <= 1'b0; retired <= 32'd0; st <= ST_RUN; err <= 3'd0;
        pause_pend <= 1'b0; stepping <= 1'b0; step_done <= 1'b0;
        state <= start ? S_FETCH : S_PAUSE;
    end
    S_PAUSE: begin
        if (resume_req) begin
            stepping <= 1'b0; state <= S_FETCH;
        end else if (step_req) begin
            stepping <= 1'b1; step_done <= 1'b0; state <= S_FETCH;
        end
    end
    S_FETCH: begin
        if (pause_pend || (stepping && step_done)) begin
            pause_pend <= 1'b0; stepping <= 1'b0; step_done <= 1'b0;
            state <= S_PAUSE;
        end else if ((pending || irq) && !in_h) begin
            pending <= 1'b0;
            if (cfg_has_handler) begin
                saved_pc <= pc; pc <= cfg_handler; in_h <= 1'b1;
                disp_retired <= retired; disp_pc <= pc;
                disp_count <= disp_count + 16'd1;
            end
        end else if (pc >= cfg_len) begin
            fail(3'd2);
        end else begin
            state <= S_EXEC;
        end
    end
    S_EXEC: case (op)
        OP_NOP:    advance;
        OP_HALT:   begin retired <= retired + 32'd1; st <= ST_HALT; state <= S_IDLE; end
        OP_ADD:    begin wr(add_r); advance; end
        OP_SUB:    begin wr(sub_r); advance; end
        OP_MUL:    begin wr(mul_r); advance; end
        OP_MAC:    begin wr(mac_r); advance; end
        OP_MULI:   begin wr(muli_r); advance; end
        OP_MOV:    begin wr(rb); advance; end
        OP_LDI:    begin wr(irw); advance; end
        OP_HORNER: begin wr(hq_r); advance; end
        OP_REDP:   begin wr(redp_r); advance; end
        OP_LIX:    begin wx({5'd0, imm}); advance; end
        OP_ADDIX:  begin wx(xb + simm); advance; end
        OP_ADDX:   begin wx(xb + xc); advance; end
        OP_MULX:   begin wx(xb * xc); advance; end
        OP_FTOX:   begin wx({11'd0, rb}); advance; end
        OP_LD:     if (!addr_ok) fail(3'd6); else state <= S_MEM;
        OP_ST:     if (!addr_ok) fail(3'd6); else advance;
        OP_JMP:    jump(target);
        OP_BEQX:   jump(xa == xb ? target : pc1);
        OP_BNEX:   jump(xa != xb ? target : pc1);
        OP_BLTX:   jump(xa <  xb ? target : pc1);
        OP_BZ:     jump(ra == 5'd0 ? target : pc1);
        OP_BNZ:    jump(ra != 5'd0 ? target : pc1);
        OP_CALL:   if (sp == 4'd8) fail(3'd3);
                   else begin stack[sp[2:0]] <= pc1; sp <= sp + 4'd1; jump(target); end
        OP_RET:    if (sp == 4'd0) fail(3'd4);
                   else begin sp <= sp - 4'd1; jump(stack[sp[2:0] - 1'b1]); end
        OP_RETI:   if (!in_h) fail(3'd5);
                   else begin in_h <= 1'b0; handled <= 1'b1; jump(saved_pc); end
        OP_WAITI:  if (handled) advance; else begin step_done <= 1'b1; state <= S_FETCH; end
        default:   fail(3'd1);
    endcase
    S_MEM: begin wr(dm_q); advance; end
    endcase
end

endmodule
